'use strict';

// MODULES //

var assign = require( './assign.js' );


// MAIN //

/**
* Extracts property values from an input object array and assigns results to elements in a new output array.
*
* @param {Array} x - input array
* @param {string} prop - property to extract
* @returns {Array} output array
*
* @example
* var x = [
*     {
*         'a': 1
*     },
*     {
*         'a': 2
*     },
*     {
*         'a': 3
*     }
* ];
*
* var y = pluck( x, 'a' );
* // returns [ 1, 2, 3 ]
*/
function pluck( x, prop ) {
	var out = new Array( x.length );
	return assign( x, prop, out, 1, 0 );
}


// EXPORTS //

module.exports = pluck;
